import React, { useState } from 'react';
import { parseEventDate, getRegion } from '../data/timeline';
import { v4 as uuidv4 } from 'uuid';

function CopyBtn({ text }) {
  const [copied, setCopied] = useState(false);
  const handle = () => { navigator.clipboard?.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); };
  return (
    <button onClick={handle} style={{ fontSize: 11, padding: '4px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: copied ? 'var(--green)' : 'var(--ink-3)', background: 'var(--paper-card)', cursor: 'pointer' }}>
      {copied ? '✓ Copied' : 'Copy all'}
    </button>
  );
}

// ── Per-book note editor ─────────────────────────────────────────
function BookNoteEditor({ bookNote, book, onChange, onDelete }) {
  return (
    <div style={{ background: 'var(--paper-2)', border: `1px solid ${book.color}33`, borderLeft: `3px solid ${book.color}`, borderRadius: 8, padding: '12px 14px', marginBottom: 10 }}>
      {/* Book header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 10 }}>
        <div style={{ width: 9, height: 9, borderRadius: '50%', background: book.color }} />
        <span style={{ fontSize: 12, fontWeight: 500, color: book.color, fontStyle: 'italic', flex: 1 }}>{book.title}</span>
        <span style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic' }}>{book.author}</span>
        <button onClick={onDelete} style={{ fontSize: 10, color: 'var(--ink-4)', cursor: 'pointer', background: 'none', border: 'none', padding: '0 2px', marginLeft: 4 }}
          onMouseEnter={e => e.currentTarget.style.color = 'var(--red)'}
          onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>✕</button>
      </div>
      {/* Quote */}
      <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>Quote</div>
      <textarea value={bookNote.quote || ''} onChange={e => onChange({ ...bookNote, quote: e.target.value })}
        placeholder="A passage from this book…"
        rows={2}
        style={{ width: '100%', resize: 'vertical', padding: '7px 10px', fontSize: 13, borderRadius: 6, fontStyle: 'italic', color: 'var(--ink-2)', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-serif)', marginBottom: 8 }} />
      {/* Note */}
      <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>Your note</div>
      <textarea value={bookNote.note || ''} onChange={e => onChange({ ...bookNote, note: e.target.value })}
        placeholder="How does this author frame the event? What angle do they take?"
        rows={3}
        style={{ width: '100%', resize: 'vertical', padding: '7px 10px', fontSize: 13, borderRadius: 6, color: 'var(--ink)', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', fontFamily: 'var(--font-serif)' }} />
    </div>
  );
}

// ── Read-only book perspective card ─────────────────────────────
function BookPerspectiveCard({ bookNote, book, showIndex, index }) {
  const [copied, setCopied] = useState(false);
  const copyText = [bookNote.quote && `"${bookNote.quote}"`, bookNote.note].filter(Boolean).join('\n\n');
  return (
    <div style={{ background: 'var(--paper-card)', border: `1px solid var(--paper-3)`, borderTop: `3px solid ${book.color}`, borderRadius: 10, padding: '16px 16px 14px', display: 'flex', flexDirection: 'column', gap: 10 }}>
      {/* Book header — only show on first note */}
      {(!showIndex || index === 0) && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 7, paddingBottom: 10, borderBottom: `1px solid ${book.color}22` }}>
          <div style={{ width: 10, height: 10, borderRadius: '50%', background: book.color, flexShrink: 0 }} />
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 13, fontWeight: 500, color: book.color, fontStyle: 'italic' }}>{book.title}</div>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 1 }}>{book.author}{book.year ? ` · ${book.year}` : ''}</div>
          </div>
          <button onClick={() => { navigator.clipboard?.writeText(copyText); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
            style={{ fontSize: 10, color: copied ? 'var(--green)' : 'var(--ink-4)', cursor: 'pointer', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
            {copied ? '✓' : 'copy'}
          </button>
        </div>
      )}
      {/* Note index label for subsequent notes */}
      {showIndex && index > 0 && (
        <div style={{ fontSize: 9, color: book.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.06em', opacity: 0.7 }}>
          note {index + 1}
        </div>
      )}
      {/* Quote */}
      {bookNote.quote && (
        <blockquote style={{ borderLeft: `2px solid ${book.color}55`, paddingLeft: 10, margin: 0, fontSize: 13, color: 'var(--ink-2)', fontStyle: 'italic', lineHeight: 1.7 }}>
          "{bookNote.quote}"
        </blockquote>
      )}
      {/* Note */}
      {bookNote.note && (
        <p style={{ fontSize: 13, color: 'var(--ink)', lineHeight: 1.7, margin: 0 }}>
          {bookNote.note}
        </p>
      )}
      {!bookNote.quote && !bookNote.note && (
        <p style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic' }}>No notes yet for this book.</p>
      )}
    </div>
  );
}

// ── Main EventDetailPage ─────────────────────────────────────────
export default function EventDetailPage({ event, books, eventTypes, onUpdate, onBack }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState({ ...event, bookNotes: event.bookNotes || [] });

  const parsed = parseEventDate(event.dateRaw);
  const region = getRegion(event.region);
  const evType = eventTypes.find(t => t.id === event.type) || { label: event.type, color: '#8a8680', bg: '#f2f0ec' };
  const linkedBooks = books.filter(b => (event.bookIds || []).includes(b.id));

  // Export text
  const exportText = [
    `# ${event.title}`,
    `**Date:** ${parsed.display || event.dateRaw}`,
    `**Region:** ${region.label}`,
    `**Type:** ${evType.label}`,
    event.tags?.length ? `**Tags:** ${event.tags.map(t => '#' + t).join(' ')}` : '',
    '',
    ...linkedBooks.map(book => {
      const bns = (event.bookNotes || []).filter(n => n.bookId === book.id);
      const notesText = bns.length
        ? bns.map((n, i) => [
            bns.length > 1 ? `### Note ${i + 1}` : '',
            n.quote ? `> "${n.quote}"` : '',
            n.note || '',
          ].filter(Boolean).join('\n')).join('\n\n')
        : '';
      return [`## ${book.title} — ${book.author}`, notesText, ''].join('\n');
    }),
  ].filter(l => l !== undefined).join('\n');

  // Draft handlers
  const updateBookNote = (bookId, updated) => {
    setDraft(d => ({ ...d, bookNotes: d.bookNotes.map(bn => bn.bookId === bookId ? updated : bn) }));
  };
  const addBookNote = (bookId) => {
    if (draft.bookNotes.find(bn => bn.bookId === bookId)) return;
    setDraft(d => ({ ...d, bookNotes: [...d.bookNotes, { bookId, quote: '', note: '' }], bookIds: [...new Set([...(d.bookIds || []), bookId])] }));
  };
  const removeBookNote = (bookId) => {
    setDraft(d => ({
      ...d,
      bookNotes: d.bookNotes.filter(bn => bn.bookId !== bookId),
      bookIds: (d.bookIds || []).filter(id => id !== bookId),
    }));
  };
  const handleSave = () => { onUpdate(draft); setEditing(false); };

  // Books not yet in the event
  const unusedBooks = books.filter(b => !draft.bookNotes.find(bn => bn.bookId === b.id));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Header */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10, flexShrink: 0, background: 'var(--paper-2)' }}>
        <button onClick={onBack} style={{ fontSize: 13, color: 'var(--ink-3)', cursor: 'pointer', background: 'none', border: 'none', display: 'flex', alignItems: 'center', gap: 4 }}>
          ← Timeline
        </button>
        <div style={{ width: 1, height: 16, background: 'var(--paper-3)' }} />
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 16, fontWeight: 600, color: 'var(--ink)', lineHeight: 1.3 }}>{event.title}</div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 3, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 12, color: 'var(--ink-3)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{parsed.display || event.dateRaw}</span>
            <span style={{ fontSize: 10, padding: '1px 8px', borderRadius: 10, background: evType.bg + '55', color: evType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{evType.label}</span>
            <span style={{ fontSize: 10, padding: '1px 8px', borderRadius: 10, background: region.color + '22', color: region.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{region.label}</span>
            {event.tags?.map(tag => (
              <span key={tag} style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>#{tag}</span>
            ))}
          </div>
        </div>
        <span style={{ fontSize: 11, color: 'var(--ink-4)' }}>{linkedBooks.length} book{linkedBooks.length !== 1 ? 's' : ''}</span>
        <CopyBtn text={exportText} />
        <button onClick={() => setEditing(e => !e)} style={{ fontSize: 12, padding: '5px 14px', borderRadius: 6, border: `1px solid ${editing ? 'var(--accent-2)' : 'var(--paper-3)'}`, color: editing ? 'var(--accent)' : 'var(--ink-2)', background: editing ? 'var(--accent-light)' : 'var(--paper-card)', cursor: 'pointer' }}>
          {editing ? 'Preview' : 'Edit'}
        </button>
        {editing && <button onClick={handleSave} style={{ fontSize: 12, padding: '5px 16px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Save</button>}
      </div>

      {/* Body */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '20px 22px' }}>
        {/* ── EDIT MODE ── */}
        {editing ? (
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--ink-4)', letterSpacing: '0.07em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 14 }}>Per-book quotes & notes</div>

            {draft.bookNotes.map(bn => {
              const book = books.find(b => b.id === bn.bookId);
              if (!book) return null;
              return (
                <BookNoteEditor key={bn.bookId} bookNote={bn} book={book}
                  onChange={updated => updateBookNote(bn.bookId, updated)}
                  onDelete={() => removeBookNote(bn.bookId)} />
              );
            })}

            {/* Add another book */}
            {unusedBooks.length > 0 && (
              <div style={{ marginTop: 8 }}>
                <div style={{ fontSize: 11, color: 'var(--ink-4)', marginBottom: 6, fontStyle: 'italic' }}>Add another book's perspective:</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                  {unusedBooks.map(b => (
                    <button key={b.id} onClick={() => addBookNote(b.id)}
                      style={{ fontSize: 11, padding: '4px 12px', borderRadius: 20, cursor: 'pointer', border: `1px solid ${b.color}55`, background: b.color + '11', color: b.color, display: 'flex', alignItems: 'center', gap: 5 }}>
                      <div style={{ width: 6, height: 6, borderRadius: '50%', background: b.color }} />
                      + {b.title}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        ) : (
          /* ── READ MODE ── */
          <div>
            {linkedBooks.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 14, lineHeight: 1.7 }}>
                No books linked yet.<br />Click Edit to add book perspectives.
              </div>
            ) : linkedBooks.length === 1 ? (
              /* Single book — full width */
              <div style={{ maxWidth: 680 }}>
                {linkedBooks.map(book => {
                  const bns = (event.bookNotes || []).filter(n => n.bookId === book.id);
                  const notes = bns.length ? bns : [{ bookId: book.id, quote: '', note: '' }];
                  return notes.map((bn, idx) => (
                    <BookPerspectiveCard key={bn.id || idx} bookNote={bn} book={book} showIndex={notes.length > 1} index={idx} />
                  ));
                })}
              </div>
            ) : (
              /* Multiple books — side by side grid */
              <div>
                <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', marginBottom: 16 }}>
                  {linkedBooks.length} books discuss this event — comparing perspectives:
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: `repeat(${Math.min(linkedBooks.length, 3)}, 1fr)`, gap: 14, alignItems: 'start' }}>
                  {linkedBooks.map(book => {
                    const bns = (event.bookNotes || []).filter(n => n.bookId === book.id);
                    const notes = bns.length ? bns : [{ bookId: book.id, quote: '', note: '' }];
                    return (
                      <div key={book.id} style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                        {notes.map((bn, idx) => (
                          <BookPerspectiveCard key={bn.id || idx} bookNote={bn} book={book} showIndex={notes.length > 1} index={idx} />
                        ))}
                      </div>
                    );
                  })}
                </div>

                {/* Synthesis prompt */}
                <div style={{ marginTop: 20, padding: '14px 18px', background: 'var(--accent-light)', border: '1px solid var(--accent-2)', borderRadius: 10 }}>
                  <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 6 }}>Your synthesis</div>
                  <textarea defaultValue={event.synthesis || ''}
                    onBlur={e => onUpdate({ ...event, synthesis: e.target.value })}
                    placeholder="What do these accounts have in common? Where do they diverge? Which framing do you find more convincing, and why?"
                    rows={4}
                    style={{ width: '100%', resize: 'vertical', padding: '8px 10px', fontSize: 13, borderRadius: 7, background: 'var(--paper-card)', border: '1px solid var(--accent-2)', color: 'var(--ink)', fontFamily: 'var(--font-serif)', lineHeight: 1.65 }} />
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
